"""Render evidence-backed CS comparison; never alter predictions or gold."""
import collections,re,subprocess,time
from cs_common import *

def md(x):return str(x).replace('|','\\|').replace('\n',' ')
def tuple_text(x):return ' / '.join(str(x[k]) for k in ('Task','Dataset','Metric','Result'))
def write(path,lines):
    path=RUN/path;path.parent.mkdir(parents=True,exist_ok=True);path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
def main():
    setup();frozen=verify();conf=read(RUN/'config.json');summary=read(RUN/'normalization/summary.json');load=read(RUN/'model_load_validation.json');model=read(RUN/'model_manifest.json')
    raw=read(BASE/'merged/output.json');norm=read(RUN/'normalization/embedding_normalized_output.json');gold=read(conf['gold_path']);paired=read(RUN/'evaluation/paired_records.json');counts=read(RUN/'evaluation/paired_summary.json');met=read(RUN/'evaluation/metrics_with_f1.json');oldmet=read(BASE/'evaluation/metrics_with_f1.json');strict=read(RUN/'evaluation/strict_result_metrics.json');per=read(RUN/'evaluation/per_paper_metrics.json');oldper=read(BASE/'evaluation/per_paper_metrics.json')
    lbdir=RUN/'leaderboard_evaluation';lb=read(lbdir/'paper_metrics/leaderboard_metrics.json')['aggregate'];oldlb=read(LB/'paper_metrics/leaderboard_metrics.json')['aggregate'];boards=read(lbdir/'leaderboards/gold_vs_predicted.json');oldboards=read(LB/'leaderboards/gold_vs_predicted.json');traces=read(lbdir/'paper_metrics/tuple_conversion_audit.json')
    audits=[json.loads(s) for s in (RUN/'normalization/mapping_audit.jsonl').read_text(encoding='utf-8').splitlines()];audit={(x['paper_id'],x['record'],x['field']):x for x in audits}
    assert len(audits)==852 and len(paired)==284 and len(norm)==43
    assert sha(BASE/'merged/output.json')==sha(RUN/'work/output.json')==sha(RUN/'merged/output.json')
    assert len(read(RUN/'candidate_labels.json')['labels']['Task'])==23
    assert len(read(RUN/'candidate_labels.json')['labels']['Dataset'])==71
    assert len(read(RUN/'candidate_labels.json')['labels']['Metric'])==26
    for x in paired:
        for k in ('Task','Dataset','Metric'):assert audit[x['paper'],x['record'],k]['selected']==x['cs'][k]
    for name,h in model['code_files_sha256'].items():
        actual=CACHE/'modules/transformers_modules/dangvantuan/bilingual_impl'/CODE_REV/name
        assert sha(actual)==h
    model.update(actual_runtime=load,actual_imported_code_matches_pinned_repository=True)
    save(RUN/'model_manifest.json',model)
    git=subprocess.run(['git','-c','safe.directory='+REPO.as_posix(),'status','--porcelain'],cwd=REPO,text=True,capture_output=True,check=True);assert not git.stdout.strip()
    commit=subprocess.run(['git','-c','safe.directory='+REPO.as_posix(),'rev-parse','HEAD'],cwd=REPO,text=True,capture_output=True,check=True).stdout.strip();assert commit=='8bf74b0a830feb7035c6166dce3394dc344ae532'
    verify()
    verification={'status':'PASS','papers':43,'gold_tdmrs':295,'predicted_tdmrs':284,'mapping_audit_fields':852,'frozen_directories':{p:{'file_count':len(v),'file_list_and_sha256_unchanged':True} for p,v in frozen['directories'].items()},'source_gold_hashes_unchanged':True,'official_git_commit':commit,'git_clean':True,'dependency_versions_unchanged':True,'raw_copy_byte_identical':True,'paper_record_order_results_sources_unchanged':True,'all_labels_in_full_gold_candidates':True,'original_main_executed':True,'actual_code_matches_pinned_revision':True,'official_result_iim_unchanged':True,'strict_result_unchanged':True,'new_remote_inference_requests':0,'pdf_parsing_runs':0,'retrieval_embedding_runs':0,'chroma_runs':0,'name_embedding_allowed':True,'top1_ties':summary['top1_tie_cases'],'official_rc_above_one':[b['tdm_key'] for b in boards if b['Result Coverage']>1]}
    save(RUN/'verification.json',verification)
    save(RUN/'api_usage_summary.json',{'new_llm_requests':0,'new_remote_inference_requests':0,'new_api_tokens':0,'download_only_network':True,'reused_extraction':str(BASE/'merged/output.json'),'local_normalization_seconds_including_load_and_smoke':summary['seconds'],'elapsed_since_local_preparation_seconds':time.time()-conf['started_epoch'],'model_download_time_not_in_inference_seconds':True})
    save(RUN/'manifest.json',{'status':'COMPLETE','papers':[{'id':p,'gold_count':len(gold[p]['TDMs']),'prediction_count':len(norm[p]['normalized_output']),'state':'COMPLETE','checkpoint':str(RUN/'normalization/papers'/Path(p).stem),'input_sha256':digest(raw[p])} for p in norm],'gold_path':conf['gold_path'],'extraction_source':str(BASE/'merged/output.json'),'normalization_output':str(RUN/'normalization/embedding_normalized_output.json')})
    tdm_table=['| 指标 | LLM P | LLM R | LLM F1 | CS P | CS R | CS F1 |','|---|---:|---:|---:|---:|---:|---:|']
    for k,v in met['aggregate'].items():
        o=oldmet['aggregate'][k];tdm_table.append('| '+k+' | '+' | '.join(f'{x:.6f}' for d in (o,v) for x in (d['Precision'],d['Recall'],d['F1']))+' |')
    lb_names={'LR_exact_tdm_hit':'LR：标准 TDM 命中','LR_nonempty_finite_result':'有效数值非空榜率','PC_official':'官方 PC','RC_official':'官方 RC','RBO_official_value_rankings':'官方数值列表 RBO','AO_paper_id_macro_all_gold_boards':'论文 ID AO（补充）'}
    lb_table=['| 指标 | LLM 标准化 | CS 标准化 |','|---|---:|---:|']+[f'| {label} | {oldlb[k]:.6f} | {lb[k]:.6f} |' for k,label in lb_names.items()]
    write(Path('evaluation/comparison_with_llm_normalization.md'),['# 同一抽取结果的配对评价','','43 篇，295 条 Gold，284 条模型预测。P/R 由原版脚本逐篇计算后取 Macro 平均；F1=2PR/(P+R)，不是逐篇 F1 的算术平均。','']+tdm_table+['',f'严格 Result P/R/F1：{strict["aggregate"]}；与 LLM 版本逐篇及聚合均一致。','', '## 排行榜','']+lb_table)
    compare=['# 全部逐条配对结果','','以下为 Gold 离线核对。严格完整 TDMR 命中采用三个标准名称完全相同及有限 Decimal Result 相等，不等同于官方包含式 Result 匹配，也不能单凭不命中断言语义错误。','','| 论文 / 序号 | 原始抽取 | LLM | CS | LLM/CS 严格 Gold 序号 | 分类 |','|---|---|---|---|---|---|']
    for x in paired:compare.append(f'| {x["paper"]} / {x["record"]} | {md(tuple_text(x["raw"]))} | {md(tuple_text(x["llm"]))} | {md(tuple_text(x["cs"]))} | {x["llm_strict_gold_indices"]} / {x["cs_strict_gold_indices"]} | {x["category"]} |')
    write(Path('evaluation/paired_comparison.md'),compare)
    gr=['# 每条 Gold 与预测对应','','编号均从 1 开始；未命中不自动修复。','','| 论文 / Gold 序号 | Gold T/D/M/R | 同数值预测序号 | LLM 严格完整命中 | CS 严格完整命中 |','|---|---|---|---|---|']
    for x in read(RUN/'evaluation/gold_alignment.json'):gr.append(f'| {x["paper"]} / {x["gold_index"]} | {md(tuple_text(x["gold"]))} | {x["strict_numeric_prediction_indices"]} | {x["llm_strict_tdmr_prediction_indices"]} | {x["cs_strict_tdmr_prediction_indices"]} |')
    write(Path('evaluation/tdmr_comparison.md'),gr)
    cases={'缩写 ON5E/WN16/WN17/RE/WE':lambda x:x['raw']['Dataset'] in ('ON5E','WN16','WN17','RE','WE'),'CoNLL-2003 语言':lambda x:bool(re.search(r'conll.?0?3|conll.2003',str(x['raw']),re.I)),'OntoNotes 版本':lambda x:'ontonot' in str(x['raw']).lower() or 'ontonot' in str(x['cs']).lower(),'IWSLT 方向':lambda x:'iwslt' in str(x['raw']).lower(),'ROUGE / ROGUE':lambda x:'rouge' in x['raw']['Metric'].lower() or 'rogue' in x['raw']['Metric'].lower(),'GLUE 及子任务':lambda x:'glue' in str(x['raw']).lower(),'Intent Detection and Slot Filling':lambda x:'Intent Detection and Slot Filling' in (x['llm']['Task'],x['cs']['Task'])}
    findings=['# 映射案例与错误记录','','按实际输入字符串筛选所有相关记录；完整原始/LLM/CS 元组见 evaluation/paired_comparison.md。所有相似度来自实际选择调用，精确保留项无伪造分数。','','配对统计（按 284 条预测，不按 295 条 Gold）：双方严格完整命中 74；仅 CS 命中 33；仅 LLM 命中 9；双方均未严格完整命中 168。旧 null 119 个字段全部得到候选名称；这只是原版强制 Top-1 的行为。','', 'WN16/WN17 映射到正确的 WNUT 标准名称；ON5E→BC5CDR、RE→RTE、WE→WNUT-16 则是错误强制映射，Result 正确仍不能形成正确 TDMR。CONLL03 不含语言信息时，德语任务字段不会被 CS Dataset 编码看到，因此也映射为 English。','', 'ROUGE-1/2 常映射到 Gold 中拼写为 ROGUE-1/2 的标准名称；ROUGE-L→BLEU、ROUGE-L F1→F1 是实际失败。大小写及输入词组不同可能得到不同结果，例如 Rouge-L→ROGUE-L；未按结果重新选择写法。','', 'GLUE→SNIPS，联合语言理解任务→Language Modeling，是错误强制归属；抽取把具体子任务写在 Metric、Dataset 只写 GLUE 的结构也保持不变。Sentence Accuracy→Accuracy 会丢失 Sent-Accuracy 区别。','', 'IWSLT 的若干 De-En 输入→Gold 标签 IWSLT’14 EN-DE 得到形式上的匹配，但输入与标签的方向文字相反，不能据此宣称翻译方向正确。wang19f 的 German→English 输入甚至被映射到 CoNLL-2003 - German。所有 Gold 命中与语义争议分别保留。']
    for title,predicate in cases.items():
        selected=[x for x in paired if predicate(x)];findings+=['',f'## {title}（{len(selected)} 条）','','| 论文 / 序号 | 字段 | 原始 → LLM → CS | CS Top-1 | 完整元组分类 |','|---|---|---|---:|---|']
        for x in selected:
            for k in ('Task','Dataset','Metric'):
                a=audit[x['paper'],x['record'],k];score='精确保留' if a['exact_match'] else f'{a["top1_score"]:.6f}'
                findings.append(f'| {x["paper"]} / {x["record"]} | {k} | {md(x["raw"][k])} → {md(x["llm"][k])} → {md(x["cs"][k])} | {score} | {x["category"]} |')
    write(Path('inspection/findings.md'),findings)
    changes=[]
    for a,b in zip(oldboards,boards):
        assert a['tdm_key']==b['tdm_key']
        if a['empty']!=b['empty']:changes.append({'tdm':b['tdm_key'],'change':'became_empty' if b['empty'] else 'became_nonempty','old_entries':len(a['predicted_official_numeric']),'new_entries':len(b['predicted_official_numeric']),'cs_trace':b['numeric_conversion_trace'],'old_trace':a['numeric_conversion_trace']})
    save(lbdir/'comparison_with_llm.json',{'LLM':oldlb,'CS':lb,'nonempty_changes':changes})
    blines=['# 排行榜对照','','同一冻结的 27 榜、140 条记录，所有 27 榜参与 Macro；不为预测新增至少三篇过滤。LR 与有效非空榜率分开。','']+lb_table+['','## 非空榜变化','','| TDM | 变化 | 旧条数 | 新条数 |','|---|---|---:|---:|']
    blines += [f'| {md(x["tdm"])} | {x["change"]} | {x["old_entries"]} | {x["new_entries"]} |' for x in changes]
    blines += ['', 'Gigaword ROGUE-1/2 来自原始 ROUGE-1/2 的 CS 映射；WNUT-16/17 包括 WN16/WN17 缩写映射；FNMI 榜来自对应指标名称的 CS 映射。XSum ROGUE-L 消失：原始 ROUGE-L F1 被映射为 F1。每条转换与后写覆盖记录均保存在 comparison_with_llm.json 和 leaderboards/gold_vs_predicted.json。','',f'共有 {traces["matching_gold_tdm_rows"]} 条预测匹配 27 榜的 TDM；其中 {len(traces["unparseable_matching_rows"])} 条 Result 无法按官方规则转换，{len(traces["overwritten_matching_rows"])} 条较早有效记录被同论文同 TDM 的后写记录覆盖；最终 {sum(len(b["predicted_official_numeric"]) for b in boards)} 条榜内预测。另 {len(traces["outside_27_board_rows"])} 条不属于这 27 个 TDM。','',f'实际 RC 最大值 {max(b["Result Coverage"] for b in boards):.6f}，没有超过 1；没有裁剪。额外论文条目数 {sum(len(b["extra_predicted_papers"]) for b in boards)}。RC 按数值命中，不要求同论文对应；RBO 使用去重数值列表，不能重命名为论文 ID AO。','', '## 各榜','','| TDM | Gold/CS 条数 | PC | RC | RBO | 论文 ID AO | 额外论文 |','|---|---:|---:|---:|---:|---|']
    for b in boards:blines.append(f'| {md(b["tdm_key"])} | {len(b["gold_ranking"])}/{len(b["predicted_ranking"])} | {b["Paper Coverage"]:.6f} | {b["Result Coverage"]:.6f} | {b["official_RBO_value_ranking"]:.6f} | {b["AO_paper_id_ranking"]:.6f} | {md(b["extra_predicted_papers"])} |')
    write(Path('leaderboard_evaluation/comparison_with_llm.md'),blines)
    report=['# GPT-4.1 + 原版 CS：全量复现报告','','完成 43/43 篇、295 条 Gold 的评价，复用 284 条原始 GPT-4.1 Extraction。没有重新抽取、解析 PDF 或构建检索索引。新增远程推理/API 请求为 0。','', '## 方法与模型','',f'执行固定 commit `{commit}` 的未修改 `tdm_embedding_normalization.main`。适配仅将原来的模型构造器指向固定本地快照，返回 CPU FP32 实例，并对原版 semantic_search 返回值及逐篇完成结果做日志记录；候选构建、精确分支、encode、top_k=1 选择和输出逻辑保持原版。','',f'模型 `{MODEL}`；权重 revision `{REV}`；实现代码 `{CODE}` revision `{CODE_REV}`。实际动态导入代码已与下载文件 SHA256 对照。Transformer → mean Pooling → Normalize；1024 维，无额外 Prompt。`PYTHONHASHSEED=0` 在启动前设置，原版 set→list 的实际顺序保存在 candidate_labels.json。','', '现有 Python 3.11.17、torch 2.2.0+cpu、NumPy 1.26.4、Transformers 4.37.2、Sentence Transformers 3.0.1 可以直接加载；未安装或升级任何包。使用 XLMRobertaTokenizerFast 和现有 tokenizer.json，未因缺少 sentencepiece 包而安装依赖。','',f'全部 284 条预测包含 852 个名称字段：310 个精确保留，542 个 CS Top-1 映射。候选为 23 Task、71 Dataset、26 Metric。实际最高分并列 {summary["top1_tie_cases"]} 次。旧 LLM 有 119 个 null，新 CS 为 0；集合内输出不等于语义正确。','', '## TDMR / IIM','']+tdm_table+['', 'P/R 保留官方逐篇 Macro；表内 F1 为聚合 P/R 的调和平均。另存逐篇 F1 均值，不与此表混用。',f'严格数值 Result P={strict["aggregate"]["Precision"]:.6f}、R={strict["aggregate"]["Recall"]:.6f}、F1={strict["aggregate"]["F1"]:.6f}；Result IIM 与严格 Result 都与旧版本完全一致。','', '## Leaderboard-level','']+lb_table+['', '标准 TDM 命中 25/27；有效非空 24/27。相对旧版本新增 5 个非空榜、1 个榜变为空。详细榜名、转换及覆盖原因见 leaderboard_evaluation/comparison_with_llm.md。','', '保持冻结 Gold：27 榜、140 条榜内记录。本地完整 Gold 含 141 个唯一 TDM、33 个至少三篇的分组，与论文统计的已知差异没有通过修改 Gold 消除。','', '## 配对诊断','', '相同抽取输入下，严格完整 TDMR 命中：双方 74 条、仅 CS 33 条、仅 LLM 9 条、双方均未命中 168 条。这些是预测记录计数，不是官方 Macro 得分或独立 Gold 覆盖数。','', '正确案例：WN16→WNUT-16 - English、WN17→WNUT-17 - English；失败案例：ON5E→BC5CDR、RE→RTE、WE→WNUT-16 - English、ROUGE-L→BLEU、GLUE→SNIPS。联合任务的 Sentence Accuracy→Accuracy 丢失了指标区别。IWSLT 的形式匹配与方向争议分开记录；未手工修正。全部重点案例见 inspection/findings.md。','', '## 耗时、内存、完整性','',f'模型加载及短名称测试约 {load["load_seconds"]:.3f} 秒；正式程序含加载、单篇验证及 43 篇标准化共 {summary["seconds"]:.3f} 秒，不含模型下载和后续评价。峰值工作集约 {summary["memory"]["peak_working_set_GiB"]:.3f} GiB，峰值私有提交约 {summary["memory"]["peak_private_GiB"]:.3f} GiB；两者含义不同。运行结束可用物理内存约 {summary["memory"]["physical_available_GiB"]:.3f} GiB，存在内存余量较小的实际限制。','', 'full43_uncapped、leaderboard_eval_full43_uncapped 的文件名集合及逐文件 SHA256 全部未变；官方源码、Prompt、Gold、依赖版本未变；Git 工作区干净。原始副本按字节相同；43 篇的 ID、记录顺序/数量、Result 字符串和 source_documents 均保留。verification.json 保存验收结论，freeze_before.json 保存证据清单。','', '## 后续状态','', '本地模型加载、名称编码、全量候选及两级评价已具备运行条件，可以准备原版 Partially Pre-defined。下一阶段仍需按官方定义核对掩蔽配置、候选集合及对应输入；本轮没有启动 Partially、Cold Start、Few-shot 或任何优化实验。','', '## 文件索引','', '- normalization/embedding_normalized_output.json：官方兼容预测。','- normalization/mapping_audit.jsonl：852 个字段的实际映射记录。','- evaluation/metrics_with_f1.json、per_paper_metrics.json：总体及逐篇指标。','- evaluation/paired_comparison.md、tdmr_comparison.md：284 条预测配对与295 条 Gold 对齐。','- leaderboard_evaluation/：原版 PC/RC/RBO 与复用的 LR/AO 评价、各榜与转换轨迹。','- candidate_labels.json、model_manifest.json、config.json：候选顺序、固定版本与配置。','- README.md、verification.json、freeze_before.json：续跑说明及完整性核验。']
    write(Path('report.md'),report)
    perlines=['# 逐篇 CS 指标','','| 论文 | Gold | 预测 | Result F1 | TDM F1 | TDMR F1 |','|---|---:|---:|---:|---:|---:|']
    for p,m in per.items():perlines.append(f'| {p} | {len(gold[p]["TDMs"])} | {len(norm[p]["normalized_output"])} | {m["Result IIM"]["F1"]:.6f} | {m["TDM Exact Match"]["F1"]:.6f} | {m["TDMR Exact Match"]["F1"]:.6f} |')
    write(Path('evaluation/per_paper_metrics.md'),perlines)
    save(RUN/'reproducibility/dependency_versions.json',frozen['dependencies'])
